// Generated from the product specification. Output catalogues for both modules and the field taxonomy.
export const M1_PHASES = [{"roman":"I","title":"Idea interpretation, scientific background and scenario definition","items":[{"id":1,"t":"Original Thought Experiment Record","d":"Complete preservation of the user-supplied prompt, original concept, hypotheses, conjectures, uploaded evidence, constraints, instructions and requested deliverables."},{"id":2,"t":"Consolidated Thought Experiment Scenario","d":"A clear, scientifically and logically structured reconstruction of the user's idea, identifying the central concept, proposed phenomenon, experiment setting and intended investigation."},{"id":3,"t":"Experiment Classification","d":"Classification into scientifically computable, logically analysable, speculative or counterfactual categories, including hybrid classifications and the reasons for each designation."},{"id":4,"t":"Background and Conceptual Foundation","d":"Relevant scientific knowledge, historical context, theoretical developments, conceptual origins and established understanding associated with the user's idea."},{"id":5,"t":"Purpose and Scientific Premise","d":"Explanation of the underlying scientific question, philosophical challenge, theoretical premise, mathematical conjecture or imagined phenomenon."},{"id":6,"t":"Research Problem and Central Question","d":"A precise statement of what the thought experiment aims to investigate, explain, establish, challenge or predict."},{"id":7,"t":"Primary and Secondary Objectives","d":"Scientific, theoretical, logical, mathematical, experimental and computational objectives derived from the supplied scenario."},{"id":8,"t":"Hypothesis and Conjecture Register","d":"All hypotheses, conjectures, propositions and predicted relationships presented separately, with their assumptions and intended tests."},{"id":9,"t":"Existing Scientific Knowledge Assessment","d":"What is known, partially understood, disputed, unverified or unsupported concerning the proposed phenomenon."},{"id":10,"t":"Scientific Domain Identification","d":"Relevant branches of physics, mathematics, chemistry, astronomy, cosmology, engineering, philosophy, computer science or other applicable disciplines."},{"id":11,"t":"Interdisciplinary Connections","d":"Identification of interactions among scientific and conceptual fields relevant to the thought experiment."},{"id":12,"t":"Conceptual Novelty Assessment","d":"Preliminary evaluation of the proposed idea's originality compared with identifiable prior research, mathematical formulations and known thought experiments."},{"id":13,"t":"Literature and Prior-Theory Comparison","d":"Relevant published models, theoretical arguments, experiments, known conjectures and competing explanations, with references and evidence limitations."},{"id":14,"t":"Experiment Scope and Boundaries","d":"Definition of what the investigation includes, excludes, assumes and deliberately leaves unresolved."},{"id":15,"t":"Experiment Feasibility Classification","d":"Assessment of whether the idea is physically testable, mathematically computable, logically decidable, experimentally inaccessible or primarily speculative."},{"id":16,"t":"Scientific and Logical Uncertainty Register","d":"Explicit identification of unknown principles, undefined concepts, incomplete information, questionable assumptions and unresolved contradictions."}]},{"roman":"II","title":"System conceptualisation, design and foundational representation","items":[{"id":17,"t":"Conceptual System Overview","d":"Description of the complete hypothetical or physical system, its components, interactions, environment and expected behaviour."},{"id":18,"t":"Physical or Abstract System Selection","d":"Selection of appropriate particles, fields, bodies, materials, logical entities, information states, spacetime configurations or abstract mathematical objects."},{"id":19,"t":"System Architecture and Component Hierarchy","d":"Organisation of system elements, subsystem relationships, interactions, dependencies and information pathways."},{"id":20,"t":"Conceptual Design","d":"A proposed arrangement of the thought experiment's elements, including how they interact and what conditions define the experiment."},{"id":21,"t":"Geometry and Spatial Configuration","d":"Geometric descriptions, dimensions, coordinates, reference shapes, spatial arrangements, surfaces, volumes and relative positions where meaningful."},{"id":22,"t":"Foundational Dimensions","d":"Relevant physical dimensions, characteristic scales, spatial dimensions, temporal dimensions, abstract dimensions and domain-specific coordinate quantities."},{"id":23,"t":"Dimensionality and Degrees of Freedom","d":"Description of whether the system is zero-, one-, two-, three- or higher-dimensional, together with the variables needed to describe its states."},{"id":24,"t":"Domain and Subdomain Definitions","d":"Spatial domains, temporal domains, logical domains, phase spaces, state spaces, mathematical manifolds and their boundaries."},{"id":25,"t":"Coordinate Systems and Reference Frames","d":"Appropriate Cartesian, cylindrical, spherical, curvilinear, inertial, rotating, comoving, relativistic or abstract coordinate representations."},{"id":26,"t":"Fundamental Entities and Interactions","d":"The particles, fields, objects, agents, variables, forces, interactions or logical relations on which the experiment depends."},{"id":27,"t":"Conceptual Apparatus and Experimental Configuration","d":"A proposed physical or imaginary apparatus, including layout, components, functional mechanisms and interaction paths."},{"id":28,"t":"Environment and Surrounding Conditions","d":"Relevant laboratory, terrestrial, marine, atmospheric, planetary, deep-space, gravitational, electromagnetic or explicitly invented environments."},{"id":29,"t":"External Influence Identification","d":"Relevant disturbances, external forces, background fields, environmental factors and possible confounding effects."},{"id":30,"t":"System Preparation and Initialisation Concept","d":"How test particles, fields, objects, materials or theoretical states are prepared before the investigation begins."},{"id":31,"t":"State Variables and Observables","d":"Variables describing the system and the physical, logical or mathematical quantities that can potentially be observed or inferred."},{"id":32,"t":"System Interaction Diagrams","d":"Visual diagrams showing how entities influence one another, transfer information or exchange physical quantities."}]},{"roman":"III","title":"Data collection, input completion and external knowledge integration","items":[{"id":33,"t":"Complete Required Input Data Register","d":"All scenario-specific physical constants, mathematical parameters, geometry, material properties, operating variables, assumptions, environmental conditions and experimental information required by the proposed investigation."},{"id":34,"t":"User-Supplied Input Register","d":"An exact record of parameters, statements, numerical values, files, datasets and assumptions directly provided by the user."},{"id":35,"t":"Uploaded File Interpretation","d":"Extracted and interpreted data from relevant documents, spreadsheets, scientific datasets, CAD files, images, simulation files and other supported inputs."},{"id":36,"t":"Missing Input Identification","d":"All missing information, undefined variables, unknown coefficients, incomplete conditions and uncertainties preventing a complete formulation or simulation."},{"id":37,"t":"Software-Supplied Input Data","d":"Credible estimates, literature values, reference constants, calculated values or explicitly assumed quantities supplied by the software."},{"id":38,"t":"Input Provenance and Traceability","d":"Labels distinguishing user-supplied, software-supplied, observed, derived, retrieved, estimated and hypothetical inputs."},{"id":39,"t":"Input Assumption Justification","d":"Explanations of why particular values, approximations or modelling assumptions have been adopted."},{"id":40,"t":"Alternative Input Sets","d":"Multiple scientifically defensible or hypothetical parameter sets for uncertain, disputed or counterfactual scenarios."},{"id":41,"t":"Scientific Knowledge Retrieval","d":"Relevant information from scientific databases, technical literature, trusted repositories, research publications and other appropriate sources."},{"id":42,"t":"Geographical and Environmental Data","d":"Applicable location, topography, bathymetry, ocean, climate, weather and environmental information for geographically dependent experiments."},{"id":43,"t":"Astronomical and Space Data","d":"Relevant celestial positions, orbital elements, planetary properties, astronomical observations, gravitational parameters and space-environment data."},{"id":44,"t":"Scientific Data Quality Assessment","d":"Source reliability, data uncertainty, measurement quality, metadata completeness and compatibility with the proposed scenario."},{"id":45,"t":"Data Currency and Retrieval Record","d":"Source publication dates, observation times, retrieval timestamps, refresh status, cache versions and warnings about stale information."},{"id":46,"t":"Data Preparation and Transformation","d":"Unit conversions, coordinate transformations, interpolations, filtering, nondimensionalisation, dataset reconciliation and other necessary preprocessing."},{"id":47,"t":"Input Sufficiency Assessment","d":"Identification of which investigations can proceed, which require assumptions and which cannot be responsibly computed using the available information."},{"id":48,"t":"Reproducible Input Dataset","d":"A complete machine-readable record of every input, assumption, source, uncertainty estimate and transformation actually used."}]},{"roman":"IV","title":"Foundational reasoning, assumptions and first-principles identification","items":[{"id":49,"t":"Foundational Scientific Principles","d":"Identification of conservation laws, dynamics, thermodynamics, electromagnetism, quantum principles, relativity, symmetry principles or other established foundations applicable to the experiment."},{"id":50,"t":"Foundational Logical Principles","d":"Applicable rules of inference, logical systems, consistency requirements, mathematical definitions and reasoning frameworks."},{"id":51,"t":"Foundational Axioms","d":"Explicit axioms defining the mathematical or logical structure of the proposed investigation."},{"id":52,"t":"Foundational Postulates","d":"Established or newly proposed postulates on which the model depends, clearly distinguished by evidential status."},{"id":53,"t":"Foundational Physical Laws","d":"Relevant established physical laws and a statement of whether the thought experiment preserves, modifies or rejects them."},{"id":54,"t":"Proposed Hypothetical Laws","d":"Explicit alternative laws or imagined interactions necessary for speculative or counterfactual investigations."},{"id":55,"t":"Assumption Register","d":"Complete specification of physical, mathematical, logical, geometric, temporal, probabilistic and computational assumptions."},{"id":56,"t":"Assumption Dependency Map","d":"Identification of which definitions, equations, predictions and conclusions depend on each assumption."},{"id":57,"t":"Reality-Compatibility Assessment","d":"Comparison between the scenario's proposed mechanisms and established scientific knowledge."},{"id":58,"t":"Logical Consistency Assessment","d":"Detection of contradictory premises, circular reasoning, incompatible definitions and mutually inconsistent assumptions."},{"id":59,"t":"Physical Consistency Assessment","d":"Checks for conservation, causality, thermodynamic consistency, symmetries, dimensional consistency and other applicable requirements."},{"id":60,"t":"Alternative Foundational Frameworks","d":"Comparison of different physical theories, logical systems, mathematical assumptions and candidate explanations for the same scenario."},{"id":61,"t":"Model Selection and Idealisation","d":"Choice of a particle, field, continuum, quantum, relativistic, statistical, discrete, stochastic, abstract or hybrid model."},{"id":62,"t":"Theoretical Framework Construction","d":"Organisation of the relevant principles, assumptions, variables, mathematical relationships and predictions into a coherent framework."},{"id":63,"t":"Foundational Compatibility and Conflict Report","d":"Identification of relationships between established laws and new assumptions, including what must change for the proposed scenario to be internally consistent."},{"id":64,"t":"Formal Scientific Premise Statement","d":"A precise expression of the principles, constraints and assumptions from which the investigation proceeds."}]},{"roman":"V","title":"Mathematical formulation, equation generation and derivation","items":[{"id":65,"t":"Mathematical Problem Definition","d":"Formal definition of the system, independent and dependent variables, domains, constraints, assumptions and required solutions."},{"id":66,"t":"Mathematical Symbol Register","d":"Complete definitions of symbols, operators, vectors, tensors, coefficients, constants, units and mathematical conventions."},{"id":67,"t":"Step-by-Step Mathematical Formulation","d":"A sequential mathematical construction of the proposed model from its foundational statements."},{"id":68,"t":"Established Governing Equations","d":"Applicable conservation, field, motion, transport, equilibrium, wave, statistical or other recognised mathematical equations."},{"id":69,"t":"First-Principles Derivation of Governing Equations","d":"Derivation of governing relationships from valid fundamental laws, with intermediate mathematical steps and explicit assumptions."},{"id":70,"t":"Alternative Governing-Equation Formulations","d":"Equivalent, approximate or competing formulations that may describe the same thought experiment under different assumptions."},{"id":71,"t":"Proposed Novel Model Equations","d":"Candidate original mathematical formulations representing hypothesised phenomena, new coupling mechanisms or modified physical behaviour."},{"id":72,"t":"Novel Constitutive and Closure Equations","d":"Proposed relationships between variables that are not completely determined by conservation laws alone."},{"id":73,"t":"Hypothetical Physical-Law Equations","d":"Mathematical representations of alternative laws introduced for speculative or counterfactual experiments."},{"id":74,"t":"Coupled Multiphysics Equations","d":"Equations representing interactions between multiple physical mechanisms, such as electromagnetic fields and fluids, spacetime curvature and matter, or heat and mechanical deformation."},{"id":75,"t":"Coupled Logical–Mathematical Models","d":"Formulations linking discrete logical states, decision rules, constraints and mathematical dynamics where relevant."},{"id":76,"t":"Source and Sink Terms","d":"Expressions representing generation, removal, exchange, emission, absorption, transformation or interaction of modelled quantities."},{"id":77,"t":"Initial Conditions","d":"Complete initial configurations of relevant fields, particles, coordinates, velocities, states and other dependent variables."},{"id":78,"t":"Boundary Conditions","d":"Applicable geometric, temporal, spatial, mathematical or hypothetical boundary constraints."},{"id":79,"t":"Interface and Transition Conditions","d":"Conditions describing boundaries between phases, materials, fields, spacetime regions, system states or conceptual domains."},{"id":80,"t":"Conservation and Balance Relations","d":"Checks and derivations concerning mass, energy, momentum, angular momentum, charge, probability or other conserved quantities."},{"id":81,"t":"Symmetry and Invariance Relations","d":"Identification of relevant rotational, translational, temporal, gauge, coordinate or other symmetry properties."},{"id":82,"t":"Dimensional Analysis","d":"Verification of physical units and dimensional structure, including applicable dimensionless parameters."},{"id":83,"t":"Nondimensional Mathematical Formulations","d":"Scaled versions of the governing equations and identification of controlling dimensionless groups."},{"id":84,"t":"Analytical Simplifications","d":"Reduced equations for limiting conditions, idealised systems, negligible effects or dominant physical mechanisms."},{"id":85,"t":"Approximate and Perturbation Solutions","d":"Appropriate perturbative expansions, asymptotic approximations, linearisation or reduced-order solutions."},{"id":86,"t":"Mathematical Theorems and Propositions","d":"Formally stated mathematical results arising from the experiment's assumptions."},{"id":87,"t":"Supporting Lemmas","d":"Intermediate mathematical statements needed to establish larger results."},{"id":88,"t":"Mathematical Proofs","d":"Symbolic, deductive or formal proofs for statements that can actually be established from the stated assumptions."},{"id":89,"t":"Counterexamples and Disproofs","d":"Mathematical constructions showing where proposed conjectures, relationships or universal claims fail."},{"id":90,"t":"Logical and Mathematical Contradiction Reports","d":"Identification of inconsistent conditions, impossible requirements or contradictory deductions."},{"id":91,"t":"Mathematical Existence and Uniqueness Assessment","d":"Examination of whether solutions exist, whether they are unique and under what assumptions such properties hold."},{"id":92,"t":"Mathematical Well-Posedness Assessment","d":"Evaluation of whether the model has sufficient information and appropriate mathematical properties to produce meaningful solutions."},{"id":93,"t":"Causality and Temporal-Ordering Assessment","d":"Examination of time ordering, signal propagation, causal relationships and theoretical causality restrictions where relevant."},{"id":94,"t":"Equation Provenance and Dependency Graph","d":"A traceable representation linking each equation to its foundational laws, assumptions, transformations and data."},{"id":95,"t":"Mathematical Formulation Completeness Report","d":"Identification of missing equations, unknown coefficients, unspecified conditions and unresolved mathematical dependencies."},{"id":96,"t":"Publication-Quality LaTeX Equation Package","d":"Professionally formatted mathematical equations, derivations, symbolic definitions and mathematical statements ready for research documentation."}]},{"roman":"VI","title":"Novel theory, equation discovery and conceptual innovation","items":[{"id":97,"t":"Scientific Knowledge-Gap Analysis","d":"Identification of phenomena or proposed relationships that existing theories do not adequately explain."},{"id":98,"t":"New Theoretical Hypothesis Generation","d":"Candidate explanations or mathematical mechanisms that could account for the imagined or observed phenomenon."},{"id":99,"t":"New Physical Interaction Hypotheses","d":"Proposed force laws, field interactions, particle couplings, transport mechanisms or other candidate interactions."},{"id":100,"t":"New Mathematical Relationship Discovery","d":"Candidate equations obtained from symbolic regression, mathematical search, dimensional analysis, data fitting or constrained optimisation."},{"id":101,"t":"New Dynamical-System Formulations","d":"Proposed descriptions of how a hypothetical system evolves through time."},{"id":102,"t":"New Particle, Field or State Models","d":"Mathematical representations of proposed entities or states, together with the consequences of their definitions."},{"id":103,"t":"New Constitutive and Material-Behaviour Models","d":"Hypothetical relationships for unconventional matter, metamaterials, unknown phases or imagined physical media."},{"id":104,"t":"Nonlocal, Memory-Dependent and Delayed Models","d":"Candidate mathematical descriptions involving history-dependent behaviour, spatial nonlocality, time delays or memory kernels."},{"id":105,"t":"Nonlinear and Stochastic Model Extensions","d":"Proposed nonlinear effects, random-event mechanisms and probabilistic descriptions."},{"id":106,"t":"Alternative Spacetime and Geometrical Models","d":"Candidate descriptions involving modified spacetime geometry, alternative dimensional structures or hypothetical curvature–matter relations."},{"id":107,"t":"New Coupling Mechanisms","d":"Proposed mathematical terms linking phenomena previously modelled independently."},{"id":108,"t":"Candidate Model Ranking","d":"Comparison of competing equations according to simplicity, explanatory power, internal consistency, empirical fit and predictive performance where evidence exists."},{"id":109,"t":"Novelty and Prior-Art Assessment","d":"A literature-grounded comparison of candidate formulations with previously published equations, patents and known theories."},{"id":110,"t":"Falsifiable Predictions","d":"Precise predictions that would distinguish the proposed theory from accepted alternatives."},{"id":111,"t":"Discriminating Experiment Recommendations","d":"Experiments or observations most capable of separating competing mathematical explanations."},{"id":112,"t":"Theoretical Readiness Assessment","d":"Classification of candidate equations according to their mathematical consistency, numerical test results and available empirical evidence."},{"id":113,"t":"Scientific Innovation and Discovery Record","d":"A documented history of generated candidate ideas, equations, modifications, supporting arguments and rejected proposals."}]},{"roman":"VII","title":"Logical, philosophical and conceptual investigation","items":[{"id":114,"t":"Formal Proposition Set","d":"Translation of the thought experiment into explicit propositions, predicates, definitions and logical conditions."},{"id":115,"t":"Premise–Conclusion Structure","d":"A formal record of what is assumed, what is argued and what is claimed to follow."},{"id":116,"t":"Logical Argument Tree","d":"A graphical or structured map of deductions, intermediate conclusions, dependencies and inferential steps."},{"id":117,"t":"Deductive Reasoning Results","d":"Conclusions obtained through valid inference rules from the supplied premises."},{"id":118,"t":"Inductive and Abductive Reasoning Assessment","d":"Evaluation of generalisations and candidate explanations, with the uncertainty and limits of such reasoning stated."},{"id":119,"t":"Truth Tables and Logical Evaluations","d":"Truth assignments, logical equivalences, satisfiability results and consistency tests."},{"id":120,"t":"Possible-World Semantics","d":"Representations of alternative logically possible systems, including worlds satisfying different combinations of assumptions."},{"id":121,"t":"Counterfactual Logical Analysis","d":"Conditional analysis of what would follow if particular facts, premises or structural assumptions were changed."},{"id":122,"t":"Paradox and Self-Reference Analysis","d":"Identification of circularity, logical paradoxes, self-reference and problems involving inconsistent definitions."},{"id":123,"t":"Consistency and Satisfiability Results","d":"Whether the formalised propositions admit a model, and whether contradictions can be established."},{"id":124,"t":"Formal Proof and Countermodel Outputs","d":"Valid deductions, proof certificates where available, countermodels and counterexamples."},{"id":125,"t":"Conceptual Distinction and Definition Analysis","d":"Identification of ambiguous concepts, incompatible definitions, category errors and alternative interpretations."},{"id":126,"t":"Philosophical Interpretation","d":"Relevant epistemological, metaphysical, ontological or methodological interpretations of the thought experiment."},{"id":127,"t":"Argument Strength and Limitation Assessment","d":"Identification of valid conclusions, unsupported leaps, hidden premises and disputed assumptions."},{"id":128,"t":"Conditional Logical Conclusions","d":"Clear statements specifying what follows necessarily, what follows only under additional assumptions and what remains undecidable."}]},{"roman":"VIII","title":"Experimental design, apparatus and measurement","items":[{"id":129,"t":"Experimental Testability Assessment","d":"Determination of whether a thought experiment can be implemented physically, approximated in a laboratory, tested indirectly or explored only mathematically."},{"id":130,"t":"Experiment Objectives and Test Plan","d":"Defined experimental questions, required observations, proposed stages and evidence criteria."},{"id":131,"t":"Physical Apparatus Design","d":"Conceptual or detailed specifications for test chambers, instruments, structures, particle systems, optical equipment or other relevant apparatus."},{"id":132,"t":"Apparatus Materials and Equipment Register","d":"Materials, sensors, instruments, components, measuring equipment and technical specifications."},{"id":133,"t":"Test Particle and Physical System Preparation","d":"Proposed preparation of particles, fields, material samples, specimens or other experimental states."},{"id":134,"t":"Experimental Geometry and Configuration","d":"Apparatus arrangement, dimensions, source and detector locations, test sections and experimental boundaries."},{"id":135,"t":"Experimental Setup Procedure","d":"Sequential instructions for arranging the experiment and establishing the intended operating environment."},{"id":136,"t":"Experimental Methodology","d":"Proposed methods for changing controlled variables, acquiring observations and comparing measurements with predictions."},{"id":137,"t":"Experimental Procedure","d":"Step-by-step test sequences, operating conditions, measurement stages and completion criteria."},{"id":138,"t":"Measurement System Design","d":"Identification of physical quantities to measure and the instruments, methods or indirect inference techniques that could measure them."},{"id":139,"t":"Detection System Design","d":"Proposed systems for detecting weak signals, rare events, particle interactions, field variations or other predicted signatures."},{"id":140,"t":"Instrumentation Diagrams","d":"Sensor layouts, signal pathways, measurement connections and relevant control schematics."},{"id":141,"t":"Control Variables","d":"Variables that must be maintained within specified limits during testing."},{"id":142,"t":"Control Experiments","d":"Baseline tests, reference configurations, null experiments, comparative tests and negative controls."},{"id":143,"t":"Environmental Isolation Requirements","d":"Measures for reducing vibration, electrical interference, thermal disturbance, contamination, mechanical disturbance and other experimental influences."},{"id":144,"t":"Measurement and Data Acquisition Plan","d":"Sampling frequencies, observation intervals, measurement locations, acquisition procedures and data storage requirements."},{"id":145,"t":"Calibration Requirements and Results","d":"Required calibration standards, calibration methods, instrument bias estimates and results when real calibration measurements are available."},{"id":146,"t":"Expected Observables and Signals","d":"Predicted measurable effects, including amplitudes, frequencies, distributions, trajectories, timing relationships or transition signatures."},{"id":147,"t":"Measurement Detection Limits","d":"Instrument sensitivity, noise floor, expected signal-to-noise ratio and threshold conditions for detecting proposed effects."},{"id":148,"t":"Measurement Uncertainty Budget","d":"Sources of random and systematic error, propagated uncertainty and expected measurement limitations."},{"id":149,"t":"Experimental Safety and Precautions","d":"Identification of hazards, operating restrictions, protective systems and precautions appropriate to the proposed physical experiment."},{"id":150,"t":"Experimental Feasibility and Resources","d":"Required equipment, achievable environmental conditions, technical constraints, expertise and approximate resource needs."},{"id":151,"t":"Proposed Prototype or Demonstrator","d":"A practical experimental demonstrator for testing selected aspects of the hypothesis, where physically and technologically feasible."},{"id":152,"t":"Experimental Protocol Document","d":"A reproducible record of the proposed setup, procedures, measurements, calibration, controls and interpretation criteria."}]},{"roman":"IX","title":"Numerical methods, computation and simulation preparation","items":[{"id":153,"t":"Computational Formulation Selection","d":"Identification of whether the experiment requires algebraic, differential, stochastic, quantum, relativistic, discrete-event, agent-based, symbolic or other computational methods."},{"id":154,"t":"Analytical versus Numerical Solution Assessment","d":"Determination of whether exact solutions, approximations or numerical methods are appropriate."},{"id":155,"t":"Simulation Domain Definition","d":"Spatial, temporal, state-space or abstract domains over which the model will be evaluated."},{"id":156,"t":"Computational Geometry and Mesh","d":"Geometric discretisation and computational meshes where spatial numerical methods require them."},{"id":157,"t":"Numerical Method Selection and Justification","d":"Choice of finite-element, finite-volume, finite-difference, spectral, particle, Monte Carlo, numerical relativity or other relevant computational methods."},{"id":158,"t":"Temporal Integration Strategy","d":"Integration schemes, time-step sizes, adaptive controls and transient simulation settings."},{"id":159,"t":"Solver Configuration","d":"Linear and nonlinear solver methods, convergence tolerances, iteration limits and numerical control parameters."},{"id":160,"t":"Symbolic Computation Strategy","d":"Algebraic manipulation, formal derivation, symbolic integration, simplification, equation solving and symbolic consistency checks."},{"id":161,"t":"Logical Solver Configuration","d":"SAT, SMT, theorem-proving, model-checking or other formal-reasoning configurations where appropriate."},{"id":162,"t":"Uncertainty and Stochastic Sampling Strategy","d":"Monte Carlo, ensemble sampling, probabilistic inference or other uncertainty propagation approaches."},{"id":163,"t":"Stability and Convergence Criteria","d":"Appropriate numerical stability conditions, convergence diagnostics and error controls."},{"id":164,"t":"Computational Resource Requirements","d":"Expected CPU, GPU, memory, storage and execution resources, including estimates of computational cost."},{"id":165,"t":"Simulation Execution Plan","d":"Ordered solution stages, initialisation, dependencies, stopping conditions and required computational tests."},{"id":166,"t":"Generated Computational Code","d":"Source code implementing the proposed mathematical or logical model in suitable programming languages."},{"id":167,"t":"Reproducible Simulation Configuration","d":"Machine-readable model settings, parameter values, dependency versions, random seeds where relevant and execution commands."}]},{"roman":"X","title":"Simulation results, numerical predictions and scientific outputs","items":[{"id":168,"t":"Complete Computed Scenario Results","d":"All calculated variables, model states and numerical predictions generated by a successfully executed, sufficiently specified simulation."},{"id":169,"t":"Initial-State Results","d":"The computed or prescribed starting configuration of the hypothetical or physical system."},{"id":170,"t":"Steady-State and Equilibrium Results","d":"Stationary solutions, equilibrium configurations, stable states or fixed points where applicable."},{"id":171,"t":"Transient and Dynamical Results","d":"Time-dependent changes in particle positions, field values, physical quantities or abstract system states."},{"id":172,"t":"Particle and Object Trajectories","d":"Computed paths, velocities, accelerations, interactions and motion histories."},{"id":173,"t":"Scalar Field Distributions","d":"Applicable scalar quantities such as temperature, potential, density, pressure, probability density, curvature scalars or energy density."},{"id":174,"t":"Vector and Tensor Field Distributions","d":"Applicable force fields, velocity fields, electromagnetic fields, stress tensors, curvature tensors and other mathematically defined fields."},{"id":175,"t":"Wave and Oscillation Responses","d":"Wave propagation, dispersion, interference, reflection, resonance, standing waves and oscillatory system behaviour."},{"id":176,"t":"Energy and Momentum Transfer Results","d":"Relevant energy balances, momentum exchange, radiation transfer and conversion processes."},{"id":177,"t":"Force and Interaction Results","d":"Predicted forces, interaction strengths, coupling effects, field responses and other interaction quantities."},{"id":178,"t":"Spacetime and Relativistic Results","d":"Applicable geodesic trajectories, proper-time differences, gravitational effects, light propagation, causal structures and curvature-related quantities."},{"id":179,"t":"Quantum and Statistical Results","d":"Probability distributions, quantum-state evolution, expectation values, transition probabilities, correlation functions or other appropriate observables."},{"id":180,"t":"Nonlinear and Emergent Behaviour","d":"Critical transitions, nonlinear feedback, bifurcations, pattern formation, chaotic dynamics and collective effects."},{"id":181,"t":"Stability and Instability Results","d":"Growth or decay of perturbations, stability regions, critical parameters and thresholds of instability."},{"id":182,"t":"Statistical and Probabilistic Results","d":"Outcome distributions, ensemble statistics, event likelihoods and stochastic trajectories."},{"id":183,"t":"Hypothetical-Law Simulation Results","d":"Conditional predictions obtained from explicitly defined alternative physical laws or speculative model equations."},{"id":184,"t":"Counterfactual Scenario Results","d":"Outcomes generated under alternative assumptions, constants, initial conditions or imagined laws."},{"id":185,"t":"Logical Model Evaluation Results","d":"Truth assignments, valid deductions, satisfiability findings, state transitions and counterexamples where the experiment is primarily logical."},{"id":186,"t":"Predicted Observable Signatures","d":"Measurable or mathematically identifiable effects associated with the hypothesis."},{"id":187,"t":"Detectability Predictions","d":"Estimates of whether predicted signals could be distinguished from background noise using specified instruments or observations."},{"id":188,"t":"Threshold and Critical-Condition Results","d":"Conditions required for a proposed effect to occur, cease, intensify or change character."},{"id":189,"t":"Parameter Response Results","d":"Changes in predicted behaviour as governing coefficients, environmental conditions or assumptions vary."},{"id":190,"t":"Numerical Error and Conservation Diagnostics","d":"Numerical residuals, conservation errors, convergence histories and identified computation failures."},{"id":191,"t":"Simulation Uncertainty Results","d":"Prediction ranges and uncertainty propagation from model inputs, numerical approximations and stochastic elements."},{"id":192,"t":"Computational Performance Results","d":"Solver execution times, iteration counts, memory usage, convergence statistics and resource consumption."},{"id":193,"t":"Simulation Status and Reliability Statement","d":"Whether each result is computed, analytically derived, merely illustrated, numerically unstable, invalid or unavailable."}]},{"roman":"XI","title":"Scientific visualisations, animations and interactive representations","items":[{"id":194,"t":"Two-Dimensional Scientific Graphs","d":"Curves, trajectories, line graphs, response plots, histograms, scatter plots and parameter-dependent graphs."},{"id":195,"t":"Three-Dimensional Scientific Plots","d":"Interactive surfaces, volumetric plots, three-dimensional trajectories and spatial distributions."},{"id":196,"t":"Contour Maps and Heatmaps","d":"Visualisations of mathematically or physically defined spatial and temporal distributions."},{"id":197,"t":"Vector and Tensor Visualisations","d":"Arrows, streamlines, glyphs, directional fields, tensor representations and other relevant displays."},{"id":198,"t":"Particle and Field Animations","d":"Animated movement of particles, objects, fields, waves and evolving mathematical states."},{"id":199,"t":"Relativistic and Spacetime Visualisations","d":"Spacetime diagrams, light cones, coordinate grids, geodesic paths and curvature-related representations."},{"id":200,"t":"Quantum and Probability Visualisations","d":"Probability-density plots, state-space representations, wavefunction-related visualisations and statistical distributions."},{"id":201,"t":"Alternative-World Animations","d":"Animations showing how systems would behave under different assumed laws or counterfactual physical constants."},{"id":202,"t":"Logical Argument and Proof Diagrams","d":"Deduction trees, implication networks, proof structures, possible-world maps and counterexample visualisations."},{"id":203,"t":"Interactive Scientific Schematics","d":"Diagrams of physical systems, experimental configurations, apparatus, detection systems and interactions."},{"id":204,"t":"Engineering Drawings and Conceptual Designs","d":"Dimensioned or conceptual drawings of proposed apparatus, prototypes and mechanical arrangements."},{"id":205,"t":"Process Flowsheets and Instrumentation Diagrams","d":"Process connections, control diagrams, measurement channels and laboratory systems where applicable."},{"id":206,"t":"Geographic, Planetary and Space Visualisations","d":"Maps, satellite imagery overlays, terrain models, celestial configurations, orbital representations and environmental visualisations when relevant."},{"id":207,"t":"Multi-Scenario Comparison Charts","d":"Graphical comparisons of different theoretical assumptions, parameter sets, models or possible worlds."},{"id":208,"t":"Time-Dependent Simulation Playback","d":"Interactive controls for viewing simulated evolution, selecting quantities and inspecting individual frames."},{"id":209,"t":"Interactive Scientific Data Tables","d":"Numerical values, derived parameters, statistical summaries, predicted measurements and model comparisons."},{"id":210,"t":"Publication-Quality Figures","d":"Scientific diagrams with units, labels, legends, uncertainties, mathematical annotations and export-ready formatting."},{"id":211,"t":"Conceptual Illustrations","d":"Explicitly labelled visual interpretations of speculative phenomena that do not have an established physical representation."},{"id":212,"t":"Full Scientific Animation and Video Package","d":"Exportable animations and videos presenting simulation results or clearly distinguished conceptual scenarios."}]},{"roman":"XII","title":"Interactive assumption changes and alternative-world investigation","items":[{"id":213,"t":"Editable Assumption Catalogue","d":"Every assumption, its justification, permitted changes and dependent equations."},{"id":214,"t":"Alternative-World Configuration","d":"User-defined worlds with different laws, constants, dimensions, geometry, materials, time behaviour or logical premises."},{"id":215,"t":"Multiple Parallel Hypothesis Models","d":"Competing formulations derived from different hypotheses or foundational assumptions."},{"id":216,"t":"Automatically Regenerated Equations","d":"Updated mathematical equations and dependencies when a user changes an assumption."},{"id":217,"t":"Automatically Recomputed Simulation Results","d":"Recalculated solutions for revised inputs or models where the appropriate solver can execute successfully."},{"id":218,"t":"Side-by-Side Alternative-World Comparison","d":"Comparative displays of equations, assumptions, predicted behaviour and conclusions."},{"id":219,"t":"Assumption-to-Conclusion Dependency Graph","d":"Identification of which scientific conclusions rely on which premises."},{"id":220,"t":"Counterfactual Causal Analysis","d":"Conditional analysis of how outcomes change under alternative inputs or interventions, distinguishing causal claims from ordinary correlations."},{"id":221,"t":"Sensitivity to Foundational Laws","d":"Analysis of the consequences of modifying an assumed conservation law, symmetry principle, constitutive relationship or physical constant."},{"id":222,"t":"Sensitivity to Initial and Boundary Conditions","d":"Comparative outcomes under different initial configurations or imposed constraints."},{"id":223,"t":"Theory Robustness Comparison","d":"Identification of predictions shared by multiple models and predictions dependent on particular theoretical choices."},{"id":224,"t":"Contradiction and Paradox Explorer","d":"Interactive investigation of incompatible assumptions, logical contradictions and counterexamples."},{"id":225,"t":"Challenge-the-Explanation Interface","d":"User-directed questioning of assumptions, mathematical steps, evidence, predictions and conclusions."},{"id":226,"t":"Alternative Explanation Generator","d":"Competing explanations and models that could account for the same proposed effect."},{"id":227,"t":"Critical Assumption Ranking","d":"Ranking of assumptions according to their influence on predicted outcomes and conclusions."},{"id":228,"t":"Experiment Version Comparison","d":"Traceable comparison of original and modified scenarios, equations, parameters and conclusions."},{"id":229,"t":"Scenario Branching and Restoration","d":"Saved alternative scenarios that can be revisited, extended, compared and restored."},{"id":230,"t":"Scientific Debate and Criticism Report","d":"Structured identification of strengths, weaknesses, unresolved questions, unsupported claims and rival interpretations."}]},{"roman":"XIII","title":"Calibration, verification, validation and falsification","items":[{"id":231,"t":"Theory Verification Assessment","d":"Checks of logical consistency, mathematical derivation, dimensional correctness and compatibility with adopted premises."},{"id":232,"t":"Symbolic Equation Verification","d":"Symbolic substitution, differentiation, simplification, identity verification and algebraic consistency checks."},{"id":233,"t":"Formal Proof Verification","d":"Machine-checked proofs or independently verifiable arguments where formal proof systems can represent the problem."},{"id":234,"t":"Numerical Code Verification","d":"Checks that the implemented computational methods correctly approximate the intended mathematical equations within tested conditions."},{"id":235,"t":"Solution Verification","d":"Spatial, temporal, iterative and numerical error estimation, including convergence and refinement tests."},{"id":236,"t":"Analytical Benchmark Comparisons","d":"Results compared with known analytical or exact solutions, where available."},{"id":237,"t":"Established Theory Comparison","d":"Predicted behaviour compared against established physical theories and accepted limiting cases."},{"id":238,"t":"Experimental Calibration","d":"Parameter estimation from relevant real observations where suitable calibration data exist."},{"id":239,"t":"Independent Experimental Validation","d":"Comparison with observations or datasets not used to calibrate the model."},{"id":240,"t":"Hypothesis Falsification Assessment","d":"Identification of predictions inconsistent with accepted measurements or new experimental evidence."},{"id":241,"t":"Distinguishing Prediction Tests","d":"Comparisons of outcomes that separate the proposed hypothesis from competing explanations."},{"id":242,"t":"Sensitivity Analysis","d":"Identification of influential coefficients, parameters, conditions and assumptions."},{"id":243,"t":"Uncertainty Quantification","d":"Input uncertainty, model uncertainty, numerical error and prediction uncertainty."},{"id":244,"t":"Model Identifiability Assessment","d":"Whether observations could determine the proposed coefficients or distinguish alternative explanations."},{"id":245,"t":"Scientific Consistency Testing","d":"Checks of conservation, causality, symmetry, stability, thermodynamic restrictions and physical feasibility where applicable."},{"id":246,"t":"Logical Robustness Testing","d":"Search for counterexamples, hidden contradictions, premise sensitivity and alternative formal interpretations."},{"id":247,"t":"Scientific Validity Envelope","d":"The conditions under which the model's behaviour has been established, tested or supported by evidence."},{"id":248,"t":"Model Failure and Contradiction Report","d":"Documented cases where the model fails, diverges, contradicts known evidence or produces unreliable results."},{"id":249,"t":"Scientific Readiness Classification","d":"Clearly differentiated statuses for untested hypothesis, internally consistent formulation, numerically verified model, empirically supported model and independently validated model."},{"id":250,"t":"Further Evidence Requirements","d":"Recommended measurements, experiments, theoretical proofs, benchmark cases or additional observations needed to strengthen the model."}]},{"roman":"XIV","title":"Interpretation, scientific implications and conclusions","items":[{"id":251,"t":"Results Interpretation","d":"Explanation of the predicted or computed behaviour and its significance within the stated theoretical framework."},{"id":252,"t":"Theory-Backed Interpretation","d":"Connection between results and established scientific principles, where those principles legitimately apply."},{"id":253,"t":"Hypothesis-Based Interpretation","d":"Conditional explanation of results derived from unverified assumptions or hypothetical laws."},{"id":254,"t":"Logical Interpretation","d":"Explanation of valid deductions, consistency findings, counterexamples and unresolved logical questions."},{"id":255,"t":"Counterfactual Interpretation","d":"Explanation of what changes in the hypothetical world and why, according to its specified assumptions."},{"id":256,"t":"Expected-versus-Computed Results","d":"Comparison between predictions made before computation and outcomes generated by the model."},{"id":257,"t":"Expected-versus-Observed Results","d":"Comparison with actual observations when measured data are available."},{"id":258,"t":"Interpretation Criteria","d":"Explicit conditions and measurable signatures governing how results are evaluated."},{"id":259,"t":"Scientific Implications","d":"Potential consequences for physical theory, mathematical modelling, existing hypotheses or experimental research."},{"id":260,"t":"Philosophical and Conceptual Implications","d":"Consequences for relevant logical, epistemological, ontological or philosophical questions."},{"id":261,"t":"Contradictions with Existing Knowledge","d":"Identification of conflicts between candidate predictions and established scientific evidence."},{"id":262,"t":"Competing Interpretation Assessment","d":"Comparison of alternative explanations and the evidence supporting or weakening them."},{"id":263,"t":"Practical Feasibility Assessment","d":"Whether some or all of the proposed experiment can be physically constructed, measured or investigated with existing technology."},{"id":264,"t":"Experimental Detectability Conclusion","d":"Whether predicted effects are likely to be measurable under the defined apparatus, sensitivities and environmental conditions."},{"id":265,"t":"Theoretical Feasibility Conclusion","d":"Whether the proposed model is internally coherent and compatible with its explicitly chosen assumptions."},{"id":266,"t":"Numerical Feasibility and Efficiency Conclusion","d":"Whether the problem can be computed within available resources and with acceptable numerical accuracy."},{"id":267,"t":"Hypothesis Evaluation","d":"Evidence supporting, contradicting or failing to distinguish the proposed hypothesis."},{"id":268,"t":"Conclusion Criteria","d":"Conditions for accepting a mathematical deduction, supporting an empirical hypothesis, rejecting a candidate model or declaring an investigation inconclusive."},{"id":269,"t":"Final Scientific or Logical Conclusion","d":"A qualified statement of what has been established, computed, conjectured, falsified or left unresolved."},{"id":270,"t":"Experiment Summary","d":"A coherent summary covering the hypothesis, theoretical formulation, methodology, mathematical results, simulations, verification and interpretation."},{"id":271,"t":"Scientific Limitations","d":"Unresolved mathematical, physical, logical, computational, data-related and experimental limitations."},{"id":272,"t":"Future Research Recommendations","d":"Proposed further theoretical investigation, additional experimental measurements, alternative hypotheses and stronger validation strategies."},{"id":273,"t":"Theoretical Extensions","d":"Further candidate equations, refined assumptions, new conceptual frameworks and broader theoretical generalisations."},{"id":274,"t":"Experimental and Engineering Extensions","d":"Potential improvements to apparatus, detection methods, experimental design, prototypes and practical implementations."},{"id":275,"t":"New Thought Experiment Suggestions","d":"Additional thought experiments generated from unresolved questions, limitations or implications of the current investigation."}]},{"roman":"XV","title":"Prototyping, engineering improvement and practical realisation","items":[{"id":276,"t":"Conceptual Prototype Design","d":"Proposed physical demonstrators, experimental devices and system configurations."},{"id":277,"t":"Prototype Geometry and Component Specifications","d":"Relevant dimensions, component arrangements, material specifications and performance requirements."},{"id":278,"t":"Prototype Mathematical and Numerical Model","d":"A computational representation of the proposed demonstrator."},{"id":279,"t":"Prototype Performance Predictions","d":"Expected physical responses, operating characteristics, measurement signals and performance limits."},{"id":280,"t":"Manufacturing and Fabrication Options","d":"Suitable methods for constructing the experimental apparatus or prototype, where feasible."},{"id":281,"t":"Prototype Materials and Equipment Requirements","d":"Required materials, instruments, mechanical components, electronics and supporting equipment."},{"id":282,"t":"Engineering Design Improvements","d":"Proposed changes to improve testability, measurement quality, performance, safety or manufacturability."},{"id":283,"t":"Tuning and Control Recommendations","d":"Adjustable operating conditions, physical parameters, instrument settings and feedback-control strategies."},{"id":284,"t":"Prototype Testing and Qualification Plan","d":"Proposed experimental tests, comparison procedures, measurement requirements and qualification criteria."},{"id":285,"t":"Practical Implementation and Technology Readiness Report","d":"Assessment of what is physically achievable, technically unresolved or technologically unavailable."}]},{"roman":"XVI","title":"Programming, reporting, export and scientific reproducibility","items":[{"id":286,"t":"Generated Mathematical Source Code","d":"Executable implementations of supported mathematical formulations using appropriate programming languages."},{"id":287,"t":"Symbolic Computation Files","d":"Symbolic representations of equations, derivations, transformations and mathematical assumptions."},{"id":288,"t":"Formal Logic and Proof Files","d":"Machine-readable propositions, theorem-prover files, model-checking specifications and proof results where appropriate."},{"id":289,"t":"Solver and Simulation Configuration Files","d":"Numerical methods, tolerances, model settings, initial conditions, boundaries and simulation controls."},{"id":290,"t":"Complete Input and Output Dataset","d":"Every actual input used and every computed result produced, with units, provenance and relevant uncertainty information."},{"id":291,"t":"Geometry and CAD Export","d":"Supported geometric representations, apparatus models and relevant engineering formats."},{"id":292,"t":"Scientific Figures and Animation Exports","d":"Graphs, heatmaps, contours, schematic diagrams, interactive visualisations, videos and animation sequences."},{"id":293,"t":"Mathematical Equation Dossier","d":"All established and candidate governing equations, derivations, axioms, postulates, lemmas, theorems, proofs and associated qualifications."},{"id":294,"t":"Scientific Hypothesis Dossier","d":"Consolidated hypotheses, conjectures, candidate new laws, competing explanations, falsifiable predictions and supporting evidence."},{"id":295,"t":"Experimental Design and Measurement Dossier","d":"Apparatus, materials, setup, methods, measurement systems, controls, calibration, safety and detection requirements."},{"id":296,"t":"Numerical Simulation Dossier","d":"Computational formulations, numerical methods, convergence results, simulated behaviour, visualisations and computational diagnostics."},{"id":297,"t":"Verification, Validation and Uncertainty Dossier","d":"Mathematical checks, numerical tests, empirical comparisons, failure cases, sensitivity and uncertainty findings."},{"id":298,"t":"Alternative-World Comparison Dossier","d":"Side-by-side descriptions of different assumptions, equations, predictions and conclusions."},{"id":299,"t":"Scientific Interpretation and Conclusion Report","d":"Theoretical discussion, limitations, scientific implications, conclusions and future investigations."},{"id":300,"t":"Research Manuscript Preparation","d":"Structured research papers, mathematical appendices, methodology descriptions, result sections and figure captions."},{"id":301,"t":"Scientific Novelty and Prior-Art Dossier","d":"Search results, candidate original contributions, comparisons with known theories and outstanding novelty questions."},{"id":302,"t":"Reproducible Research Package","d":"Source code, input datasets, mathematical formulations, computation settings, source references and execution instructions."},{"id":303,"t":"Machine-Readable Scientific Model Export","d":"Structured model definitions containing equations, variables, assumptions, constraints, dependencies and experiment classifications."},{"id":304,"t":"Scenario and Model Version History","d":"Revision history of user prompts, assumptions, theoretical frameworks, mathematical equations, simulations and scientific conclusions."},{"id":305,"t":"Automated Experiment Workflow","d":"Repeatable pipelines for retrieving information, generating candidate models, executing supported simulations and producing scientific reports."},{"id":306,"t":"Batch and Ensemble Investigation Results","d":"Collections of results from systematic parameter studies, competing hypotheses, uncertainty sampling and alternative-world simulations."},{"id":307,"t":"External Integration and API Outputs","d":"Structured exchange of authorised data and model results with connected repositories, scientific software, instrumentation and other systems."},{"id":308,"t":"Security and Scientific Audit Records","d":"Access logs, calculation provenance, file integrity records, model changes, data permissions and computational traceability."},{"id":309,"t":"Final Integrated Thought Experiment Dossier","d":"A unified package of applicable conceptual, logical, mathematical, computational, experimental and interpretive outputs."}]}];
export const M2_PHASES = [{"roman":"I","title":"Scenario interpretation, scientific background and problem definition","items":[{"id":1,"t":"Original Scenario and Prompt Record","d":"The exact user-supplied scenario, objective, requirements, restrictions, uploaded materials, requested accuracy, computational limits, scientific domain and version history."},{"id":2,"t":"Consolidated Scientific and Engineering Scenario","d":"A structured, technically consistent restatement of the scenario, resolving terminology, identifying missing information and distinguishing user statements from software interpretations."},{"id":3,"t":"Background and Scientific Context","d":"Established scientific knowledge, relevant theories, engineering practices, historical developments, industrial context, applicable technologies and the current scientific understanding of the problem."},{"id":4,"t":"Purpose and Scientific Premise","d":"The principal scientific question, engineering challenge, mathematical problem, intended application, research hypothesis and desired outcome."},{"id":5,"t":"Problem Statement and Research Objectives","d":"Primary and secondary objectives, investigation boundaries, engineering requirements, performance targets, feasibility questions and specific predictions to be tested."},{"id":6,"t":"Scientific and Engineering Domain Classification","d":"Identification of all participating disciplines and subdisciplines, including the intersections between physics, engineering, chemistry, mathematics, computing and other applicable fields."},{"id":7,"t":"Physical System Overview","d":"Description of the complete system, subsystems, physical components, participating materials, operating mechanisms, external influences and interactions."},{"id":8,"t":"System Architecture and Functional Representation","d":"Functional block diagrams, subsystem hierarchies, interaction networks, energy and material pathways, information flows and dependencies."},{"id":9,"t":"Physical Phenomena Identification","d":"All relevant physical mechanisms, including fluid motion, turbulence, heat transfer, structural deformation, chemical reactions, electromagnetic effects, phase changes, diffusion, radiation, gravity and other scenario-specific phenomena."},{"id":10,"t":"Scientific Hypotheses and Model Objectives","d":"Testable hypotheses, predicted physical behaviours, theoretical propositions, expected relationships and measurable criteria for supporting or rejecting a proposed model."},{"id":11,"t":"Modelling Feasibility Assessment","d":"Evaluation of whether the scenario can be represented using current mathematical models, whether adequate data exist, which aspects remain uncertain and whether meaningful computation is possible."},{"id":12,"t":"Scope, Exclusions and Limitations","d":"Clearly documented phenomena included or excluded, modelling approximations, spatial and temporal boundaries, computational restrictions and limitations of scientific applicability."}]},{"roman":"II","title":"Data acquisition, input preparation and environmental modelling","items":[{"id":13,"t":"Complete Input Data Register","d":"A comprehensive, scenario-specific record of every input required or used by the model, including physical properties, dimensions, operating conditions, experimental measurements, material parameters and numerical settings."},{"id":14,"t":"Input Data Provenance and Classification","d":"Each input is labelled as user-supplied, uploaded, externally retrieved, directly measured, derived, estimated, software-supplied or assumed, with its source, units, timestamp and confidence or uncertainty information."},{"id":15,"t":"Software-Supplied Missing Input Data","d":"Identification of missing parameters and provision of credible values or ranges where justifiable, together with estimation methods, assumptions, sources and sensitivity implications. Unsupported values must remain unresolved rather than being presented as facts."},{"id":16,"t":"Automated Input Completion Report","d":"A comparison of original inputs, completed inputs, inferred parameters, unresolved requirements and any changes made during preprocessing."},{"id":17,"t":"Data Acquisition and External Information Retrieval","d":"Relevant scientific publications, engineering databases, geographical datasets, weather records, oceanographic observations, planetary data, material libraries and experimental repositories."},{"id":18,"t":"Data Source Reliability and Currency Report","d":"Source authority, coverage, licensing, publication date, retrieval time, measurement quality, update frequency, missing records, source disagreements and data freshness."},{"id":19,"t":"Data Cleaning and Preprocessing Results","d":"Corrected units, harmonised datasets, missing-value treatments, outlier evaluations, coordinate transformations, data filtering, interpolation and quality-control records."},{"id":20,"t":"Material and Fluid Property Datasets","d":"Relevant density, viscosity, elasticity, thermal conductivity, heat capacity, phase behaviour, chemical composition, permeability, strength and other scenario-specific properties."},{"id":21,"t":"Environmental and Geographical Data","d":"Applicable terrain, bathymetry, seabed properties, ocean currents, water depth, weather conditions, atmospheric properties, climate conditions, solar radiation, planetary environments or space-environment datasets."},{"id":22,"t":"Geometry Acquisition and Reconstruction","d":"Imported CAD models, geometric dimensions, assemblies, surfaces, volumes, centre lines, reconstructed geometries and computational representations."},{"id":23,"t":"Geometry Integrity and Repair Report","d":"Geometry defects, non-manifold regions, gaps, intersections, invalid surfaces, dimensional inconsistencies and any automatic corrections performed."},{"id":24,"t":"Coordinate Systems and Reference Frames","d":"Global and local coordinates, spatial reference systems, rotating reference frames, inertial and non-inertial frames, transformations and applicable relativistic reference conventions."},{"id":25,"t":"Domain and Subdomain Definitions","d":"Fluid regions, solids, interfaces, porous media, chemical regions, electromagnetic regions, exterior fields, moving regions and overlapping computational domains."},{"id":26,"t":"Foundational Dimensions and Characteristic Scales","d":"Characteristic length, time, velocity, temperature, mass, pressure, energy, force, concentration and other scales appropriate to the problem."},{"id":27,"t":"Data Sufficiency and Identifiability Assessment","d":"Evaluation of whether the supplied measurements and parameters are adequate to determine the model, distinguish competing hypotheses and produce reliable predictions."}]},{"roman":"III","title":"First-principles selection and mathematical model formulation","items":[{"id":28,"t":"Applicable Fundamental Laws and Principles","d":"Identification of the conservation laws, physical principles, variational formulations, symmetry requirements, thermodynamic laws and mathematical principles applicable to the scenario."},{"id":29,"t":"Foundational Axioms, Postulates and Definitions","d":"Formal statement of the relevant mathematical axioms, physical postulates, definitions and foundational modelling conventions."},{"id":30,"t":"Physical System Selection and Idealisation","d":"Choice between continuum, discrete, particle, field, stochastic, molecular, quantum, relativistic, lumped-parameter, reduced-order or hybrid system descriptions."},{"id":31,"t":"Explicit Modelling Assumptions","d":"All assumptions concerning material properties, flow behaviour, dimensionality, equilibrium, symmetry, compressibility, linearity, continuity, boundary effects and neglected phenomena."},{"id":32,"t":"Mathematical Variables and Symbol Register","d":"Every dependent variable, independent variable, coefficient, source term, material property, tensor, operator, mathematical constant and unit."},{"id":33,"t":"Model Formulation Strategy","d":"Explanation of why particular governing principles, variables, mathematical frameworks and levels of model fidelity were selected."},{"id":34,"t":"Step-by-Step First-Principles Derivations","d":"Full symbolic derivations from foundational principles to governing equations, including intermediate steps, transformations and assumptions."},{"id":35,"t":"Established Governing Equations","d":"Scenario-specific governing equations expressed as ordinary differential equations, partial differential equations, algebraic equations, differential-algebraic systems, integral equations, stochastic equations or other appropriate mathematical formulations."},{"id":36,"t":"Constitutive Relations and Closure Equations","d":"Material laws, turbulence closures, interfacial interactions, transport correlations, reaction kinetics, friction relationships, phase-transition descriptions and other auxiliary equations necessary to close the mathematical system."},{"id":37,"t":"Coupled Multiphysics Equations","d":"Mathematical descriptions of interactions between physical disciplines, including fluid–structure, thermal–structural, fluid–thermal, chemical–thermal, electromagnetic–thermal and other coupled phenomena."},{"id":38,"t":"Source, Sink and Interaction Terms","d":"Mathematical representations of forces, heat sources, chemical production, phase exchange, mass transfer, radiation, external loading, deposition, erosion and additional transport mechanisms."},{"id":39,"t":"Interface and Jump Conditions","d":"Mathematical conditions governing fluid–solid interfaces, phase boundaries, contact surfaces, moving fronts, discontinuities, interfacial transport and coupled computational regions."},{"id":40,"t":"Initial Conditions","d":"Complete initial states of the system, including field distributions, velocities, temperatures, pressures, concentrations, structural states and any scenario-specific internal variables."},{"id":41,"t":"Boundary Conditions","d":"Applicable prescribed-value, flux, mixed, periodic, symmetry, interface, moving-boundary, radiation, far-field and other mathematically appropriate boundary conditions."},{"id":42,"t":"Operating and Environmental Conditions","d":"Steady-state, transient, startup, shutdown, restart, cyclic, emergency, extreme-event and other operating configurations."},{"id":43,"t":"Model Completeness and Closure Assessment","d":"Comparison between unknowns, independent equations, necessary constitutive relations, constraints and supplied initial/boundary conditions."},{"id":44,"t":"Dimensional Analysis and Nondimensionalisation","d":"Dimensional consistency, governing dimensionless groups, characteristic ratios, dominant physical mechanisms and nondimensional equations."},{"id":45,"t":"Analytical Reductions and Limiting Cases","d":"Simplified formulations for special conditions, asymptotic limits, canonical benchmark cases and cases where exact or approximate analytical solutions are available."},{"id":46,"t":"Mathematical Properties and Solution Existence Assessment","d":"Evaluations of continuity, differentiability, conservation, stability, positivity, uniqueness, well-posedness and existence of solutions wherever such properties can be demonstrated."},{"id":47,"t":"Mathematical Proofs and Formal Arguments","d":"Machine-checkable or independently verifiable proofs where possible, including relevant lemmas, theorems, propositions and demonstrated properties of the derived mathematical model. Unproved assertions are explicitly identified."},{"id":48,"t":"Equation Dependency and Provenance Graph","d":"A traceable mathematical graph showing how equations are derived, what assumptions each depends on, where coefficients originate and which equations would change if an assumption is modified."},{"id":49,"t":"Alternative Established Mathematical Formulations","d":"Valid competing formulations, different approximation levels, alternative closure models, equivalent mathematical representations and their respective advantages and limitations."}]},{"roman":"IV","title":"Novel equation discovery and mathematical hypothesis generation","items":[{"id":50,"t":"Scientific Knowledge-Gap Identification","d":"Identification of phenomena, coupling mechanisms or response relationships that are poorly explained, inadequately modelled or insufficiently supported by existing formulations."},{"id":51,"t":"Novelty and Prior-Art Search Report","d":"Comparison of proposed equations against accessible scientific literature, patents, databases and known mathematical formulations, including similarities, differences and unresolved prior-art questions."},{"id":52,"t":"Candidate New Governing Equations","d":"Proposed new differential, integral, stochastic, nonlinear, nonlocal, fractional-order, memory-dependent or hybrid equations, where scientifically and mathematically motivated."},{"id":53,"t":"Candidate Constitutive Models","d":"Proposed material laws, closure correlations, interfacial relations, transport models, response functions and physical-property relationships."},{"id":54,"t":"Data-Driven Symbolic Equation Discovery","d":"Candidate interpretable equations identified using symbolic regression, sparse model discovery, system identification and statistical learning."},{"id":55,"t":"Physics-Constrained Equation Discovery","d":"New candidate terms, relationships and formulations constrained by conservation laws, dimensions, relevant symmetries, known physical limits and empirical evidence."},{"id":56,"t":"New Coupling-Term Formulations","d":"Proposed relationships for interactions between physical mechanisms not adequately represented by existing models."},{"id":57,"t":"Mathematical Hypothesis Catalogue","d":"Multiple competing model hypotheses, each with its assumptions, equation structure, predicted consequences, computational requirements and conditions for rejection."},{"id":58,"t":"Equation Parsimony and Complexity Assessment","d":"Ranking of candidate formulations by mathematical complexity, interpretability, predictive ability, parameter count and consistency with observations."},{"id":59,"t":"Parameter Identification and Structural Identifiability","d":"Evaluation of whether the proposed coefficients can be inferred uniquely from available data or whether multiple parameter combinations generate equivalent predictions."},{"id":60,"t":"Theoretical Consistency Assessment","d":"Examination of candidate formulations against established laws, dimensional constraints, symmetry requirements, positivity, causal assumptions and limiting behaviour."},{"id":61,"t":"Original Derivation and Innovation Record","d":"A documented account of how each proposed equation was generated, including symbolic operations, learned relationships, assumptions and computational discovery methods."},{"id":62,"t":"Falsifiable Predictions and Discriminating Experiments","d":"Predictions that distinguish candidate equations from established alternatives, along with measurements and experiments capable of rejecting incorrect hypotheses."},{"id":63,"t":"Novel-Model Scientific Readiness Report","d":"Classification of each proposal as an untested hypothesis, mathematically consistent candidate, numerically verified formulation, empirically supported model or independently validated model."}]},{"roman":"V","title":"Experimental design, measurement and detection","items":[{"id":64,"t":"Experimental Objectives and Test Plan","d":"The testable purpose of experiments, measurable outcomes, experimental stages, acceptance criteria and connections to the proposed mathematical model."},{"id":65,"t":"Experimental Design and Apparatus","d":"Complete conceptual or detailed descriptions of required experimental rigs, sensors, test sections, laboratory equipment, fixtures and measurement systems."},{"id":66,"t":"Experimental Geometry and Setup","d":"Equipment layout, physical dimensions, component placement, test-region configurations, connections, measuring locations and environmental arrangements."},{"id":67,"t":"Materials, Equipment and Instrumentation Register","d":"Material specifications, equipment characteristics, sensor types, instrument ranges, resolution, sensitivity and required calibration standards."},{"id":68,"t":"Specimen or Test-System Preparation","d":"Preparation of test particles, fluids, materials, structural specimens, biological or chemical samples, mechanical components and other appropriate experimental systems."},{"id":69,"t":"Experimental Methodology and Procedure","d":"Sequential experimental procedures, operating steps, adjustment sequences, measurement schedules and data-recording methods."},{"id":70,"t":"Measurement and Detection Strategy","d":"Definition of measurable variables, expected signals, detection techniques, sensor placement, sampling frequencies and methods for identifying the physical effects being investigated."},{"id":71,"t":"Experimental Controls and Control Variables","d":"Independent variables, dependent variables, controlled variables, nuisance variables, reference states and control-group specifications."},{"id":72,"t":"Control Experiments and Baseline Cases","d":"Baseline tests, null experiments, reference experiments, comparative scenarios and procedures for identifying confounding effects."},{"id":73,"t":"Environmental Isolation and Control Requirements","d":"Requirements for controlling temperature, humidity, vibrations, electromagnetic interference, pressure, contamination, acoustic noise or other environmental influences."},{"id":74,"t":"Data Acquisition and Measurement Procedures","d":"Sensor sampling, synchronisation, signal processing, measurement protocols, monitoring points, data formats and acquisition schedules."},{"id":75,"t":"Measurement Uncertainty and Error Budget","d":"Instrument accuracy, measurement bias, repeatability, systematic uncertainty, random error, uncertainty propagation and expected detection limits."},{"id":76,"t":"Expected Experimental Signatures","d":"Predicted measurable responses, transient signatures, spatial patterns, frequency spectra, threshold effects, phase transitions or other indicators of the hypothesised behaviour."},{"id":77,"t":"Experimental Feasibility Assessment","d":"Expected technical difficulty, availability of equipment, detectability of predicted effects, achievable operating conditions and estimated resource requirements."},{"id":78,"t":"Experimental Calibration and Quality-Control Plan","d":"Instrument calibration procedures, reference materials, traceability requirements, inspection schedules and acceptance limits."},{"id":79,"t":"Experimental Safety and Precautionary Requirements","d":"Identified experimental hazards, required protective measures, operating restrictions, emergency procedures and relevant safety controls."},{"id":80,"t":"Experimental Data and Comparison Report","d":"Measured responses, processed observations, repeatability results, discrepancies between theoretical predictions and observations, and recommendations for further testing. Actual measurements are reported only when experimental data have been supplied or connected instruments have acquired them."}]},{"roman":"VI","title":"Computational geometry, meshing and numerical model preparation","items":[{"id":81,"t":"Simulation Domain Geometry","d":"Computationally suitable geometric representation of the modelled system, including solid regions, fluid volumes, surfaces, curves, boundaries and interfaces."},{"id":82,"t":"CAD and Geometry Conversion Outputs","d":"Converted geometry files, repaired models, dimensional checks, tessellated representations and interoperable export files."},{"id":83,"t":"Computational Mesh Generation","d":"Structured, unstructured, hybrid, conforming, nonconforming, adaptive and other appropriate computational meshes."},{"id":84,"t":"Mesh Quality and Diagnostics","d":"Element size, aspect ratio, skewness, orthogonality, Jacobian quality, cell volumes, mesh conformity and invalid-element detection."},{"id":85,"t":"Spatial Discretisation Strategy","d":"Selected numerical representations and their suitability for the governing equations, geometry, discontinuities and required solution accuracy."},{"id":86,"t":"Temporal Discretisation Strategy","d":"Time integration methods, time-step sizes, adaptive time-stepping controls, temporal tolerances and transient simulation settings."},{"id":87,"t":"Numerical Methods Selection and Justification","d":"Recommended finite-volume, finite-element, finite-difference, spectral, boundary-element, particle-based, lattice-based or other appropriate numerical methods, with explanations of their suitability."},{"id":88,"t":"Numerical Solver Configuration","d":"Linear and nonlinear solvers, preconditioners, iteration limits, relaxation parameters, coupling algorithms and convergence tolerances."},{"id":89,"t":"Numerical Stability and Consistency Assessment","d":"Applicable stability criteria, numerical diffusion, dispersion, conservation properties, positivity constraints and discretisation consistency checks."},{"id":90,"t":"Mesh and Time-Step Independence Results","d":"Spatial and temporal refinement studies, convergence trends and discretisation-error estimates, when the required runs have been completed."},{"id":91,"t":"Computational Resource Requirements","d":"Estimated processor requirements, GPU needs, memory, storage, expected computational burden, parallelisation strategies and resource allocation."},{"id":92,"t":"Simulation Execution Plan","d":"Case setup, solver sequencing, dependencies, execution stages, restart strategies, convergence checkpoints and reproducibility controls."},{"id":93,"t":"Computational Model and Solver Files","d":"Generated source code, configuration files, mesh files, material definitions, boundary-condition files, initial-condition files and solver setup packages."}]},{"roman":"VII","title":"Full numerical simulation, computation and prediction","items":[{"id":94,"t":"Complete Simulation Results","d":"Numerical solutions for the scenario, including computed values of the primary and secondary variables across the appropriate spatial and temporal domains."},{"id":95,"t":"Steady-State Results","d":"Equilibrium or stationary distributions of relevant physical variables, operating points, load responses, steady-flow characteristics and other steady-system outputs."},{"id":96,"t":"Transient and Time-Dependent Results","d":"Dynamic responses, evolving fields, startup and shutdown characteristics, time histories, transient loads, wave propagation and time-dependent system behaviour."},{"id":97,"t":"Spatial Field Distributions","d":"Three-dimensional, two-dimensional and one-dimensional distributions of variables such as pressure, temperature, velocity, stresses, strain, concentration, electromagnetic fields or radiation intensity."},{"id":98,"t":"Scalar, Vector and Tensor Fields","d":"Spatial and temporal results for scalar quantities, vector fields, tensor-valued quantities, gradients, fluxes and mathematical invariants."},{"id":99,"t":"Derived Physical Quantities","d":"Quantities calculated from primary solution variables, including forces, moments, pressure losses, heat-transfer coefficients, mass-transfer rates, energy fluxes, efficiency and other context-specific outputs."},{"id":100,"t":"System Response and Performance Characteristics","d":"Functional performance of the modelled system under specified operating conditions, including effectiveness, capacity, response time and performance limitations."},{"id":101,"t":"Local and Global Conservation Results","d":"Mass, momentum, energy, charge and species conservation diagnostics, including global balance errors, local residuals and unresolved discrepancies."},{"id":102,"t":"Simulation Convergence Results","d":"Solver residuals, convergence histories, iteration counts, convergence failures, stopping criteria and numerical tolerance achievements."},{"id":103,"t":"Multiphysics Coupling Results","d":"Interactions between the individual physical models, coupling convergence, interfacial exchanges, feedback effects and cross-domain response patterns."},{"id":104,"t":"Nonlinear and Critical Behaviour","d":"Bifurcations, instabilities, critical thresholds, resonance, nonlinear transitions, hysteresis, limit cycles and other nonlinear responses where applicable."},{"id":105,"t":"Stochastic and Probabilistic Simulation Results","d":"Ensembles, probability distributions, random-event predictions, event frequencies and confidence or credible intervals, depending on the statistical formulation."},{"id":106,"t":"Multiscale Simulation Results","d":"Relationships between molecular, microscopic, mesoscopic and macroscopic behaviour where compatible multiscale descriptions have been implemented."},{"id":107,"t":"Extreme-Condition and Failure-Scenario Predictions","d":"Responses under credible extreme loads, severe environmental conditions, emergency operations, component failures and other defined stress scenarios."},{"id":108,"t":"Model Prediction Intervals and Uncertainty Bands","d":"Predicted variable ranges and probabilistic intervals accounting for explicitly modelled parameter, measurement and stochastic uncertainties."},{"id":109,"t":"Numerical Performance and Computational Efficiency","d":"Execution time, memory consumption, solver scalability, parallel efficiency, iteration statistics and computational cost."},{"id":110,"t":"Simulation Status and Integrity Report","d":"Confirmation of completed and failed cases, numerical warnings, invalid inputs, solver limitations, unresolved conditions and whether each result is suitable for interpretation."}]},{"roman":"VIII","title":"Scientific visualisation, diagrams and animation","items":[{"id":111,"t":"Two-Dimensional Graphs and Plots","d":"Line plots, scatter plots, bar charts, histograms, response curves, time-series plots and comparative visualisations."},{"id":112,"t":"Three-Dimensional Scientific Visualisations","d":"Interactive three-dimensional representations of geometric models, scalar fields, vector fields, deformation patterns and simulated physical responses."},{"id":113,"t":"Contour Maps and Heatmaps","d":"Spatial and temporal distributions of temperatures, pressure, stresses, concentration, velocities, density and other quantities."},{"id":114,"t":"Streamlines, Pathlines and Particle Trajectories","d":"Flow direction, transport patterns, particle tracking, circulation structures and temporal motion of material elements."},{"id":115,"t":"Vector and Tensor Visualisation","d":"Vector arrows, tensor glyphs, stress trajectories, principal directions, flux patterns and orientation-dependent responses."},{"id":116,"t":"Scientific Animation and Video Outputs","d":"Time-dependent animations of fluid motion, deformation, temperature evolution, particle movement, flow regimes, chemical changes and other computed processes."},{"id":117,"t":"Interactive Simulation Playback","d":"Animation timelines, pause and replay, frame-by-frame examination, variable selection, adjustable viewing angles, zooming and time synchronisation."},{"id":118,"t":"Scientific Tables and Numerical Datasets","d":"Complete numerical results in structured tables, time-series datasets, field datasets, statistical summaries and machine-readable files."},{"id":119,"t":"Engineering Drawings and Schematics","d":"System layouts, engineering diagrams, dimensioned conceptual drawings, equipment arrangements, component views and sectional representations."},{"id":120,"t":"Process Flow Diagrams and Flowsheets","d":"Material and energy pathways, process units, equipment connections, flow directions, stream properties and process dependencies."},{"id":121,"t":"Piping and Instrumentation Diagrams","d":"Piping connections, instrumentation locations, valves, pumps, measuring systems and control-loop representations where applicable."},{"id":122,"t":"Electrical, Mechanical and Multiphysics Diagrams","d":"Circuit schematics, mechanical arrangements, structural systems, coupling diagrams and relevant physical-system representations."},{"id":123,"t":"Spatial and Geographical Visualisations","d":"Terrain maps, bathymetric maps, satellite-based maps, geographical overlays, oceanographic distributions and environmental fields when geospatial information is relevant."},{"id":124,"t":"Results Comparison Dashboards","d":"Side-by-side model results, scenario comparisons, baseline comparisons, experimental overlays and alternative formulation visualisations."},{"id":125,"t":"Interactive Scientific Data Exploration","d":"Variable filters, point probes, cross-sectional interrogation, region selection, data inspection, statistical views and interactive visual analytics."},{"id":126,"t":"Publication-Quality Scientific Figures","d":"Exportable figures with units, captions, legends, scales, uncertainty markings, mathematical annotations and reproducible plotting settings."}]},{"roman":"IX","title":"Calibration, verification, validation and scientific credibility","items":[{"id":127,"t":"Model Calibration Results","d":"Estimated model coefficients, fitted parameters, calibrated material properties, objective-function values and parameter confidence intervals."},{"id":128,"t":"Calibration Dataset and Procedure Record","d":"Calibration data provenance, fitting methods, constraints, optimisation settings and separation between calibration and validation datasets."},{"id":129,"t":"Code Verification Results","d":"Evidence that implemented numerical algorithms correctly solve the intended mathematical equations to the expected numerical accuracy, within tested conditions."},{"id":130,"t":"Solution Verification Results","d":"Estimated discretisation, iterative and numerical errors in the computed solution, including mesh refinement and time-step studies."},{"id":131,"t":"Analytical Benchmark Comparisons","d":"Results compared with exact or accepted analytical solutions for suitable benchmark problems."},{"id":132,"t":"Manufactured-Solution Verification","d":"Verification results from appropriately constructed manufactured solutions, including measured orders of convergence."},{"id":133,"t":"Experimental Validation Results","d":"Comparisons between predicted results and independent experimental observations not used for calibration."},{"id":134,"t":"Industrial and Field-Data Validation","d":"Comparisons against available industrial measurements, operational data, monitoring records and established engineering benchmark cases."},{"id":135,"t":"Independent Model-to-Model Comparisons","d":"Comparisons with other credible modelling formulations or independently implemented computational methods, with differences and limitations documented."},{"id":136,"t":"Statistical Validation Metrics","d":"RMSE, MAE, relative errors, residual distributions, correlation statistics, coverage metrics, likelihood-based scores and other relevant measures."},{"id":137,"t":"Physical Consistency Verification","d":"Conservation checks, thermodynamic consistency, physically permissible ranges, symmetry tests, correct limiting behaviour and consistency with known mechanisms."},{"id":138,"t":"Numerical Robustness Assessment","d":"Solver behaviour under changes in mesh quality, parameter ranges, time-step sizes, nonlinear stiffness, operating conditions and solver controls."},{"id":139,"t":"Sensitivity Analysis Results","d":"Local and global sensitivity indices, influential parameters, parameter interactions and uncertainty-driven changes in model outputs."},{"id":140,"t":"Uncertainty Quantification Report","d":"Input uncertainty propagation, parameter uncertainty, numerical uncertainty, structural model uncertainty and associated prediction variability."},{"id":141,"t":"Model Applicability and Validity Envelope","d":"Ranges of operating conditions, geometries, material properties and phenomena for which the model has evidence of reliability."},{"id":142,"t":"Validation Gaps and Required Evidence","d":"Areas where experimental data, benchmark comparisons, theoretical justification or independent verification are missing."},{"id":143,"t":"Scientific Credibility and Readiness Assessment","d":"Evidence-based model readiness statements distinguishing formulation completeness, mathematical verification, solver verification, empirical validation and practical engineering qualification."},{"id":144,"t":"Reproducibility and Audit Report","d":"Software versions, datasets, model parameters, equations, computational settings, execution records, checksums and provenance necessary to reproduce results."}]},{"roman":"X","title":"Optimisation, tuning, intelligent control and design improvement","items":[{"id":145,"t":"Design Variables and Optimisation Objectives","d":"Identified geometry parameters, material choices, operating conditions, design constraints, performance objectives and decision variables."},{"id":146,"t":"Mathematical Optimisation Formulation","d":"Defined objective functions, equality and inequality constraints, design bounds, optimisation algorithms and stopping conditions."},{"id":147,"t":"Optimised Designs and Operating Conditions","d":"Candidate optimal geometries, component configurations, material selections, operating setpoints and process conditions."},{"id":148,"t":"Single-Objective Optimisation Results","d":"Recommended solutions minimising or maximising a specified measurable quantity, such as energy consumption, drag, pressure loss, cost, weight or thermal resistance."},{"id":149,"t":"Multiobjective Optimisation Results","d":"Pareto-optimal design candidates, trade-off surfaces and comparisons involving competing objectives, such as efficiency versus cost or weight versus strength."},{"id":150,"t":"Automated Parameter Tuning","d":"Tuned coefficients, operating parameters, model settings and numerical controls, with clearly distinguished physical calibration and numerical tuning."},{"id":151,"t":"Design-of-Experiments Results","d":"Parameter screening, factorial experiments, response-surface studies, space-filling sampling and statistical experimental designs."},{"id":152,"t":"Surrogate and Reduced-Order Models","d":"Computationally efficient representations developed from higher-fidelity models or measured data, with reported approximation errors and applicability limits."},{"id":153,"t":"Intelligent Control Strategy","d":"Proposed feedback, feedforward, adaptive, predictive or supervisory control strategies suitable for the system."},{"id":154,"t":"Controller Design and Tuning Results","d":"Controller parameters, target setpoints, response characteristics, stability margins and control-performance metrics."},{"id":155,"t":"Real-Time Monitoring and Control Outputs","d":"Live operating dashboards, measured-versus-predicted comparisons, detected deviations and recommended control interventions when connected to authorised physical systems."},{"id":156,"t":"Digital-Twin Outputs","d":"Updated model states, estimated operating conditions, measurement assimilation, fault indicators and predicted future behaviour when suitable live operational data are available."},{"id":157,"t":"Iterative Engineering Design Improvements","d":"Successive design versions, identified weaknesses, modifications, performance comparisons and recommended engineering improvements."},{"id":158,"t":"Robust and Reliability-Based Optimisation","d":"Optimised solutions accounting for operating uncertainty, material variability, failure probabilities and engineering reliability constraints."},{"id":159,"t":"Operational Recommendations and Decision Support","d":"Evidence-based recommendations for system configuration, operating envelopes, maintenance strategies, optimisation opportunities and performance improvement."}]},{"roman":"XI","title":"Safety, reliability, integrity and regulatory assessment","items":[{"id":160,"t":"Hazard Identification and Risk Register","d":"Physical, chemical, thermal, mechanical, electrical, pressure-related, environmental, operational and computational risks."},{"id":161,"t":"Failure Modes and Effects Analysis","d":"Possible component and system failures, causes, consequences, detectability, likelihood estimates where supported, and recommended mitigation measures."},{"id":162,"t":"Structural and Operational Integrity Assessment","d":"Relevant strength, stress, fatigue, fracture, buckling, corrosion, erosion, wear, containment and operational-integrity evaluations."},{"id":163,"t":"Reliability and Availability Predictions","d":"Failure probabilities, availability estimates, lifetime predictions, system reliability models and maintenance-related performance indicators where defensible input data exist."},{"id":164,"t":"Safety Factors and Engineering Margins","d":"Calculated factors of safety, allowable operating margins, predicted threshold exceedances and margins relative to specified engineering criteria."},{"id":165,"t":"Extreme-Event and Emergency-Response Assessment","d":"Modelled responses under extreme environmental conditions, abnormal operations, loss of containment, shutdowns and other defined emergency conditions."},{"id":166,"t":"Safety Controls and Mitigation Strategies","d":"Recommended safeguards, alarms, interlocks, monitoring requirements, operational restrictions and protective design features."},{"id":167,"t":"Standards and Regulatory Applicability Assessment","d":"Identification of potentially relevant engineering codes, regulatory requirements, design standards and industry guidance, with edition and jurisdiction documented."},{"id":168,"t":"Standards Compliance Evidence and Gaps","d":"Traceable checks against selected requirements, supporting calculations, missing evidence and items requiring qualified professional review."},{"id":169,"t":"Environmental Impact and Sustainability Results","d":"Energy consumption, greenhouse-gas estimates, emissions, resource demand, waste generation, discharge impacts and other relevant environmental indicators."},{"id":170,"t":"Cybersecurity and Simulation Integrity Report","d":"Access control, data provenance, upload security, model integrity, audit trails, protection against malicious inputs and safeguards for connected equipment."}]},{"roman":"XII","title":"Engineering design, prototyping, manufacturing and fabrication","items":[{"id":171,"t":"Conceptual Engineering Design","d":"Concept layouts, design alternatives, system architecture, preliminary dimensions and functional descriptions."},{"id":172,"t":"Preliminary Engineering Design Package","d":"Calculated design loads, component sizing, material requirements, operating limits and preliminary design documents."},{"id":173,"t":"Detailed Design Recommendations","d":"Design parameters, dimensional specifications, relevant material choices, component requirements and implementation constraints."},{"id":174,"t":"Prototype Development Plan","d":"Prototype requirements, development stages, test configurations, expected performance and evaluation criteria."},{"id":175,"t":"Prototype Simulation and Performance Report","d":"Predicted prototype behaviour, sensitivity to design changes, simulated failure modes and comparison with design objectives."},{"id":176,"t":"Manufacturing and Fabrication Methods","d":"Suitable fabrication processes, machining, casting, forming, welding, additive manufacturing, composite manufacturing or other relevant production techniques."},{"id":177,"t":"Manufacturing Feasibility Assessment","d":"Material availability, manufacturing tolerances, geometric complexity, process capabilities, inspection requirements and production limitations."},{"id":178,"t":"Bill of Materials and Equipment Specifications","d":"Components, materials, quantities, technical specifications and preliminary procurement requirements when enough design detail is available."},{"id":179,"t":"Manufacturing Drawings and Technical Documentation","d":"Dimensioned technical drawings, assemblies, tolerances, process notes, and exportable CAD-related deliverables to the extent supported by the design and modelling tools."},{"id":180,"t":"Fabrication and Assembly Plan","d":"Proposed fabrication sequences, assembly stages, inspection points, required equipment and manufacturing quality-control procedures."},{"id":181,"t":"Prototype Testing and Qualification Plan","d":"Mechanical, thermal, hydraulic, environmental, functional, durability and other required qualification tests."},{"id":182,"t":"Design Verification and Engineering Release Assessment","d":"Identification of whether the design meets its stated requirements and what additional analyses, physical tests, certification or responsible-engineer approval are necessary before deployment."}]},{"roman":"XIII","title":"Interactive assumption changes and alternative-world simulation","items":[{"id":183,"t":"Editable Assumption Register","d":"Every modelling assumption is presented with its original value, rationale, governing influence, source and ability to be changed by the user."},{"id":184,"t":"Alternative Scenario Generator","d":"Creation of multiple scenarios involving different physical assumptions, geometries, material properties, environments, boundary conditions and governing formulations."},{"id":185,"t":"Parallel Scenario Simulation Results","d":"Side-by-side simulations showing how alternative assumptions change system behaviour and predicted outcomes."},{"id":186,"t":"Model Equation Regeneration","d":"Automatic regeneration of the affected governing equations, closure relationships and numerical setup when the user changes a modelling assumption."},{"id":187,"t":"Assumption-to-Conclusion Dependency Mapping","d":"Identification of which predictions, interpretations and conclusions depend on specific assumptions or sets of assumptions."},{"id":188,"t":"Counterfactual Engineering Scenarios","d":"Comparison of defined alternative physical conditions or design decisions, including cases that depart from baseline practice while remaining mathematically specified."},{"id":189,"t":"Model Challenge and Criticism Report","d":"Systematic examination of whether assumptions are justified, whether rival explanations exist and whether the same evidence could support different models."},{"id":190,"t":"Alternative Theoretical Explanation Comparison","d":"Evaluation of competing theories or mechanisms against their predictions, foundational assumptions, data requirements and empirical evidence."},{"id":191,"t":"Interactive Parameter and Model-Control Dashboard","d":"User adjustment of parameters, operating settings, solver controls and eligible modelling assumptions, triggering appropriate recalculations."},{"id":192,"t":"Differential Outcome Analysis","d":"Quantification of changes in model outputs between the baseline and alternative scenarios, including relative differences, causal caveats and uncertainty."},{"id":193,"t":"Robustness of Scientific Conclusions","d":"Classification of conclusions that remain supported across tested assumptions and those that disappear, reverse or become uncertain when conditions change."},{"id":194,"t":"Scientific Debate and Evidence-Review Interface","d":"Interactive explanations in which users can question derivations, challenge data sources, request competing models and examine supporting evidence."},{"id":195,"t":"Scenario Versioning and Comparison History","d":"Saved scenario versions, parameter differences, assumptions, equations, numerical settings and output comparisons for reproducible investigations."}]},{"roman":"XIV","title":"Scientific interpretation, conclusions and research extension","items":[{"id":196,"t":"Scientific Interpretation of Results","d":"Explanation of physical meaning, mathematical behaviour, dominant mechanisms, notable trends and relationships between computed variables."},{"id":197,"t":"Theory-Backed Interpretation","d":"Interpretation grounded in established physical laws, accepted theory, measured evidence and documented modelling assumptions."},{"id":198,"t":"Interpretation Criteria","d":"Explicit thresholds, observable signatures, comparison rules and scientific standards used to evaluate results."},{"id":199,"t":"Comparison with Existing Scientific Knowledge","d":"Agreement or disagreement with published research, established correlations, accepted analytical results and observed engineering behaviour."},{"id":200,"t":"Scientific and Engineering Implications","d":"Potential consequences for scientific theory, industrial applications, engineering design, operational performance and future research."},{"id":201,"t":"Model Limitations and Sources of Disagreement","d":"Identified missing physics, uncertain coefficients, numerical approximations, incomplete measurements, extrapolation risks and unexplained result discrepancies."},{"id":202,"t":"Hypothesis Acceptance or Rejection Criteria","d":"Defined evidential thresholds for supporting, rejecting or leaving a hypothesis unresolved, without treating an individual simulation as conclusive experimental proof."},{"id":203,"t":"Feasibility and Efficiency Conclusions","d":"Assessment of whether the proposed design, model, experiment or operating scenario satisfies specified performance, accuracy, efficiency and practical feasibility requirements."},{"id":204,"t":"Scientific Conclusion","d":"A structured account of what the modelling and evidence demonstrate, what remains uncertain, and which objectives have or have not been achieved."},{"id":205,"t":"Executive and Technical Summary","d":"Concise and detailed summaries of the scenario, modelling approach, assumptions, major calculations, results, evidence and limitations."},{"id":206,"t":"Recommendations for Further Research","d":"Proposed additional experiments, more accurate models, new datasets, alternative mathematical formulations and improved numerical investigations."},{"id":207,"t":"Future Engineering Extensions","d":"Opportunities for extending the model to higher dimensions, stronger multiphysics coupling, additional equipment, other materials, new operating regimes or larger system scales."},{"id":208,"t":"Future Mathematical Extensions","d":"Potential new constitutive relationships, alternative equation forms, higher-order effects, stochastic formulations, multiscale models and novel theoretical hypotheses."},{"id":209,"t":"Research Publication Preparation","d":"Structured scientific manuscripts, model descriptions, methodology sections, equation documentation, computational results, figure captions and reproducibility appendices."},{"id":210,"t":"Intellectual Property and Research Novelty Dossier","d":"Documentation of potentially original formulations, development chronology, literature comparisons and technical differences, with clear acknowledgement that novelty and patentability require separate assessment."}]},{"roman":"XV","title":"Programming, export, reproducibility and automation","items":[{"id":211,"t":"Generated Simulation Source Code","d":"Appropriate Python, Julia, C++, MATLAB or other code implementing the selected mathematical and numerical formulations."},{"id":212,"t":"Symbolic Equation Export","d":"Mathematical equations exported as LaTeX, MathML, symbolic expressions or other supported mathematical representations."},{"id":213,"t":"Machine-Readable Model Definition","d":"Structured records of model variables, equations, parameters, units, assumptions, closures, dependencies and solution settings."},{"id":214,"t":"Solver-Ready Simulation Packages","d":"Model setup packages, configuration files, mesh data, material properties, initial and boundary conditions and execution instructions."},{"id":215,"t":"CAD and Geometry Exports","d":"Appropriate neutral geometry, CAD, mesh and scientific visualisation formats according to the selected workflow and supported conversion capabilities."},{"id":216,"t":"Experimental Protocol and Laboratory Documentation","d":"Exportable apparatus specifications, experiment procedures, instrument requirements, measurement sheets and calibration documentation."},{"id":217,"t":"Scientific Reports and Technical Documents","d":"PDF, DOCX, HTML and other reports containing derivations, assumptions, modelling methodology, equations, figures, numerical results and conclusions."},{"id":218,"t":"Numerical Data Exports","d":"CSV, HDF5, NetCDF, VTK, JSON, spreadsheets and other appropriate data formats, depending on the output and data structure."},{"id":219,"t":"Animation and Visual Media Export","d":"Scientific animations, simulation videos, image sequences, interactive scenes and high-resolution plots."},{"id":220,"t":"Comparative Scenario Reports","d":"Side-by-side comparisons of equations, assumptions, conditions, outputs, uncertainties and conclusions across simulation variants."},{"id":221,"t":"Reproducible Computational Research Package","d":"Code, dependency manifests, data provenance, computational environments, input records, deterministic seeds where applicable and execution instructions."},{"id":222,"t":"Automated Scientific Workflow Definitions","d":"Repeatable workflows for data ingestion, model generation, simulations, calibration, validation, optimisation and report production."},{"id":223,"t":"Batch Simulation and Parameter-Sweep Results","d":"Outputs from automatically executed ensembles, systematic parameter studies, uncertainty investigations and optimisation runs."},{"id":224,"t":"API and Integration Output","d":"Structured model results, job statuses, downloadable datasets, authorised notifications and data-exchange payloads for external systems."},{"id":225,"t":"Data and Model Version Control","d":"History of revised equations, input datasets, model configurations, simulation results and scientific decisions."},{"id":226,"t":"Security and Access Records","d":"Appropriate authentication and authorisation logs, model access history, data export records and controlled changes to scientific configurations."},{"id":227,"t":"Computational Cost and Resource Report","d":"Compute-hours, memory consumption, storage use, job duration and estimated resource or cloud expenditure."},{"id":228,"t":"Final Scientific Deliverables Package","d":"A configurable collection of all relevant equations, derivations, modelling assumptions, verified results, simulation outputs, scientific figures, source code and supporting documentation."}]}];
